lesson.code:
-- Em vez de ler um arquivo CSV linha a linha sem travas:
-- O banco garante atomicidade e integridade no acesso
SELECT id, nome, saldo FROM contas_bancarias WHERE id = 1042;

-- Cada linha representa uma tupla atômica completa
INSERT INTO usuarios (id, nome, email, ativo)
VALUES (1, 'Ana Silva', 'ana@empresa.com', true);

-- Busca determinística por atributos da tupla
SELECT nome FROM usuarios WHERE id = 1;

-- O SGBD gerencia locks de concorrência e buffer pool em segundo plano
BEGIN;
UPDATE contas SET saldo = saldo - 100 WHERE id = 1;
UPDATE contas SET saldo = saldo + 100 WHERE id = 2;
COMMIT; -- Salva com segurança usando Write-Ahead Logging

-- Se o segundo comando falhar por erro de rede ou constraint, nada é persistido
BEGIN TRANSACTION;
INSERT INTO pedidos (id, cliente_id, total) VALUES (55, 12, 350.00);
INSERT INTO auditoria_log (evento) VALUES ('Pedido 55 criado');
COMMIT;

-- Entidades independentes bem delimitadas no esquema relacional
CREATE TABLE clientes (
  id INT PRIMARY KEY,
  razao_social VARCHAR(150)
);

CREATE TABLE faturas (
  id INT PRIMARY KEY,
  cliente_id INT,
  valor DECIMAL(10,2)
);

-- Definindo chave primária inteira autoincrementada
CREATE TABLE produtos (
  id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  sku VARCHAR(50) NOT NULL UNIQUE,
  titulo VARCHAR(200) NOT NULL
);

-- Surrogate key imutável + Unique constraint no dado do negócio
CREATE TABLE fornecedores (
  id BIGINT PRIMARY KEY,          -- Chave surrogate imutável
  cnpj CHAR(14) NOT NULL UNIQUE,  -- Chave natural para busca
  nome_fantasia VARCHAR(120)
);

-- 1 Departamento possui N Funcionários
CREATE TABLE departamentos (
  id INT PRIMARY KEY,
  nome VARCHAR(60)
);

CREATE TABLE funcionarios (
  id INT PRIMARY KEY,
  departamento_id INT REFERENCES departamentos(id),
  nome VARCHAR(100)
);

-- Decomposição de Estudantes e Cursos em N:N
CREATE TABLE estudantes ( id INT PRIMARY KEY, nome VARCHAR(100) );
CREATE TABLE cursos ( id INT PRIMARY KEY, titulo VARCHAR(100) );

-- Criando tabela com verificações preventivas
CREATE TABLE IF NOT EXISTS categorias (
  id SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome VARCHAR(50) NOT NULL UNIQUE,
  ativo BOOLEAN NOT NULL DEFAULT true
);

