-- Tabela otimizada com consumo mínimo de bytes por linha
CREATE TABLE logs_acesso (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, -- Suporta bilhões de logs
  codigo_status SMALLINT NOT NULL,                    -- Status HTTP (ex: 200, 404)
  ip_origem VARCHAR(45) NOT NULL                     -- Suporta IPv4 e IPv6
);

-- Precisão exata obrigatória para controle fiscal e financeiro
CREATE TABLE saldos_carteira (
  usuario_id INT PRIMARY KEY,
  saldo_brl DECIMAL(14, 2) NOT NULL DEFAULT 0.00,  -- Moeda fiat padrão
  saldo_btc DECIMAL(18, 8) NOT NULL DEFAULT 0.00000000 -- Precisão de cripto
);

