lesson.code:
-- Paginação clássica (simples, mas lenta para páginas altas)
SELECT id, titulo FROM artigos ORDER BY id ASC LIMIT 10 OFFSET 20;

-- Paginação por cursor (escalável e constante em O(1))
SELECT id, titulo FROM artigos WHERE id > 540 ORDER BY id ASC LIMIT 10;

